#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N,K;
    cin>>N>>K;

    struct Nd{int id;double x,y;char type;};
    vector<Nd> nd(N+K);
    for(int i=0;i<N+K;i++) cin>>nd[i].id>>nd[i].x>>nd[i].y>>nd[i].type;

    vector<int> robots,relays;
    for(int i=0;i<N+K;i++){
        if(nd[i].type=='C') relays.push_back(i);
        else robots.push_back(i);
    }

    int NR=robots.size();
    auto dist=[&](int i,int j)->double{
        double dx=nd[i].x-nd[j].x,dy=nd[i].y-nd[j].y;
        return sqrt(dx*dx+dy*dy);
    };

    // Edge cost: relay-relay=inf, else euclidean distance
    auto ecost=[&](int i,int j)->double{
        if(nd[i].type=='C'&&nd[j].type=='C') return 1e18;
        return dist(i,j);
    };

    // All candidate nodes = robots + relays
    int T=N+K;
    // Prim's MST on robots only first
    vector<double> key(NR,1e18);
    vector<int> par(NR,-1);
    vector<bool> inM(NR,false);
    key[0]=0;
    for(int it=0;it<NR;it++){
        int u=-1;
        for(int i=0;i<NR;i++) if(!inM[i]&&(u<0||key[i]<key[u]))u=i;
        inM[u]=true;
        for(int v=0;v<NR;v++) if(!inM[v]){
            double c=ecost(robots[u],robots[v]);
            if(c<key[v]){key[v]=c;par[v]=u;}
        }
    }

    struct E{int u,v;double w;};
    vector<E> edges;
    for(int i=1;i<NR;i++) edges.push_back({robots[i],robots[par[i]],ecost(robots[i],robots[par[i]])});

    set<int> used;
    bool imp=true;
    while(imp){
        imp=false;
        for(int ri:relays){
            if(used.count(ri))continue;
            int be=-1;double bs=-1e-9;
            for(int e=0;e<(int)edges.size();e++){
                double nc=ecost(edges[e].u,ri)+ecost(edges[e].v,ri);
                double s=edges[e].w-nc;
                if(s>bs){bs=s;be=e;}
            }
            if(be>=0&&bs>1e-9){
                int u=edges[be].u,v=edges[be].v;
                edges[be]={u,ri,ecost(u,ri)};
                edges.push_back({ri,v,ecost(ri,v)});
                used.insert(ri);
                imp=true;
            }
        }
    }

    if(used.empty()) cout<<"#\n";
    else{bool f=true;for(int c:used){if(!f)cout<<"#";cout<<nd[c].id;f=false;}cout<<"\n";}
    {bool f=true;for(auto&e:edges){if(!f)cout<<"#";cout<<nd[e.u].id<<"-"<<nd[e.v].id;f=false;}cout<<"\n";}
}
